corrected_code:
import { buildSubgraphSchema } from '@apollo/subgraph';
import { GraphQLError } from 'graphql';
import gql from 'graphql-tag';
import { AppDataSource } from '../data-source';
import { Prescription } from '../entity/Prescription';

const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key"])

  type Prescription @key(fields: "id patientId") {
    id: ID!
    patientId: ID!
    medication: String!
    dosage: String!
    refillsRemaining: Int!
    deaSchedule: String!
  }
`;

export const resolvers = {
  Prescription: {
    __resolveReference: async (ref: { id: string; patientId: string }, context: any) => {
      if (!context.currentUser) {
        throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
      }
      if (context.currentUser.role !== 'DOCTOR' && context.currentUser.patientId !== ref.patientId) {
        throw new GraphQLError('Access denied to patient prescription record', { extensions: { code: 'FORBIDDEN' } });
      }
      const repo = AppDataSource.getRepository(Prescription);
      return await repo.findOne({
        where: { id: ref.id, patientId: ref.patientId },
        relations: ['doctor'],
      });
    },
  },
};
